package com.dtm.platform.validation;import java.util.*;import java.net.URI;
public final class ContentDataValidator {private ContentDataValidator(){}
 public static void validate(String resource,Map<String,Object> data){if(data==null)return;if(data.keySet().stream().anyMatch(k->k.matches("(?i).*(password|secret|api.?key|signing.?key).*")))throw new IllegalArgumentException("Credentials cannot be stored in public content");if(data.toString().length()>80000)throw new IllegalArgumentException("Content data is too large");if(data.size()>60)throw new IllegalArgumentException("Too many fields");for(String key:List.of("liveUrl","githubUrl","website","photo")){Object value=data.get(key);if(value instanceof String url&&!url.isBlank()&&!url.startsWith("/")){URI u=URI.create(url);if(!"https".equals(u.getScheme())||u.getHost()==null)throw new IllegalArgumentException("Links must use HTTPS");}}if(data.get("images") instanceof List<?> images){if(images.size()>40)throw new IllegalArgumentException("Too many images");for(Object item:images){if(!(item instanceof String image))throw new IllegalArgumentException("Invalid image link");if(!image.startsWith("/api/v1/media/")&&!image.startsWith("https://"))throw new IllegalArgumentException("Invalid image link");}}if(data.get("technologies") instanceof List<?> list&&list.size()>100)throw new IllegalArgumentException("Too many technologies");}
}
